# Analysis: CodeViewer Recreation Issue

I've reviewed the component hierarchy and identified the root cause of the CodeViewer recreation problem.

## Problem Identification

In **`Code.vue`**, the `CodeViewer` component is being recreated on every code update because it lacks a stable `key` attribute:

```vue
<CodeViewer
  :code="codeText"
  :language="language"
  :file="file"
  :files="files"
  :project="project"
  :finished="finished"
  :chat="chat"
  :message="message"
  v-if="showCode"
  @reload-file="$emit('reload-file', $event)"
  @open-file="$emit('open-file', $event)"
  @save-file="$emit('save-file', $event)"
  @add-file="$emit('add-file', $event)"
  @sub-task="$emit('sub-task', $event)"
  @message-change="onMessageChange"
/>
```

**Without a `key`**, Vue's reconciliation algorithm destroys and recreates the component whenever the parent re-renders, which happens on every code stream update via `codeText`.

## Solution

Add a stable `key` binding to `CodeViewer` that persists across streaming updates:

```vue client/src/components/Code.vue
<script setup>
import MermaidViewerVue from './MermaidViewer.vue'
import MarkdownViewer from './MarkdownViewer.vue'
import CodeViewer from './CodeViewer.vue'
</script>

<template>
  <div class="rounded-md py-2">
    <div class="flex gap-2 w-full justify-end rounded-t" ref="toolbar" v-if="showMermaid">
      <button class="btn btn-xs" @click="showMermaidSource = !showMermaidSource">
        <span v-if="showMermaidSource">View diagram</span>
        <span v-else>View code</span>
      </button>
    </div>

    <MermaidViewerVue
      :diagram="codeText"
      theme="dark"
      @click="showMermaidSource = !showMermaidSource"
      v-if="showMermaid && !showMermaidSource"
    />

    <CodeViewer
      :key="`code-viewer-${file || 'inline'}`"
      :code="codeText"
      :language="language"
      :file="file"
      :files="files"
      :project="project"
      :finished="finished"
      :chat="chat"
      :message="message"
      v-if="showCode"
      @reload-file="$emit('reload-file', $event)"
      @open-file="$emit('open-file', $event)"
      @save-file="$emit('save-file', $event)"
      @add-file="$emit('add-file', $event)"
      @sub-task="$emit('sub-task', $event)"
      @message-change="onMessageChange"
    />

    <MarkdownViewer :text="codeText" v-if="showMarkdown" />
    <div v-html="codeText" v-if="htmlPreview"></div>
  </div>
</template>

<script>
const languageMapping = {
  "vue": "html",
  "markdown": "md"
}

export default {
  props: ['chat', 'finished', 'code', 'text', 'text-language', 'file-name', 'files', 'project', 'message'],
  emits: ['reload-file', 'open-file', 'save-file', 'add-file', 'sub-task', 'edit-message', 'generate-code', 'text-changed'],
  data() {
    return {
      codeText: null,
      languages: null,
      htmlPreview: false,
      showMermaidSource: false,
      file: null,
    }
  },
  created() {
    const language = languageMapping[this.codeLanguage] || this.codeLanguage
    this.languages = [[language, language.toUpperCase()]]
    this.codeText = this.text || this.code?.innerText
    this.file = this.fileName || this.code?.attributes["data-file"]?.value
  },
  mounted() {
    if (this.code) {
      this.code?.parentNode.after(this.$el)
      this.code?.parentNode.remove()
      this.$bubble('code-file-shown', { somedata: true })
    }
  },
  computed: {
    isVibeCoding() {
      return this.chat?.mode === 'vibe'
    },
    language() {
      const lang = this.textLanguage ||
        this.code?.attributes["class"]?.value.split("-").reverse()[0]
      return languageMapping[lang] || lang
    },
    codeLanguage() {
      return this.language?.includes("mermaid") ? "markdown" : this.language
    },
    showMermaid() {
      return this.language === 'mermaid' && !this.isVibeCoding
    },
    showCode() {
      return !this.showMarkdown && (!this.showMermaid || this.showMermaidSource) && !this.htmlPreview
    },
    showMarkdown() {
      return this.language === 'md' && !this.fileName
    },
    codeBlockInfo() {
      return {
        code: this.text || this.code?.innerText,
        language: this.language
      }
    }
  },
  methods: {
    // Patch this block's content, then ask Markdown.vue to rebuild the full text
    onMessageChange({ orgContent, newContent }) {
      this.codeText = newContent
      this.rebuildMarkdownText()
    },

    // Walk sibling Code blocks inside the same Markdown container and
    // reconstruct the full markdown string, then bubble it up
    rebuildMarkdownText() {
      // Collect all Code component instances that share our $parent (Markdown.vue)
      const siblings = this.$parent?.$children?.filter(c => c.$options?.name === undefined
        ? false
        : c.codeText !== undefined) || []

      if (!siblings.length) {
        // No siblings found; emit only our own updated fence
        this.$emit('text-changed', this.buildFence(this.codeText))
        return
      }

      // Ask the parent (Markdown.vue) to rebuild from all its code blocks
      this.$emit('text-changed', { block: this, newContent: this.codeText })
    },

    buildFence(content) {
      const lang = this.language || ''
      const fileHint = this.file ? ` ${this.file}` : ''
      return `\`\`\`${lang}${fileHint}\n${content}\n\`\`\``
    }
  }
}
</script>
```

## Key Change

```diff
    <CodeViewer
+     :key="`code-viewer-${file || 'inline'}`"
      :code="codeText"
      ...
```

**Why this works:**
- Uses the `file` property as the stable identifier (if available) or defaults to `'inline'` for inline code blocks
- The key only changes when the actual file changes, not during code streaming
- Vue preserves the component instance across `codeText` updates
- Code streaming now displays incrementally as updates arrive instead of recreating the entire editor

This ensures **CodeViewer maintains its internal state and DOM continuity**, allowing the streamed code to appear smoothly as it's generated.

# Analysis

I can see the issue clearly. The code is using `block.hash` as the key in the `v-for` loop in `ChapterBlock.vue`, but since the hash is computed from the content and content changes during streaming, the key becomes unstable and causes the component to be recreated unnecessarily.

## The Problem

In `ChapterBlock.vue` (line with the repeating code):
```vue
<div v-for="block in blocks" :title="`${block.type} - ${block.fileName}`" :key="block.hash">
```

During streaming, `block.content` changes → `block.hash` changes → Vue treats it as a different item → component recreates.

## The Solution

We need a **stable index-based key** that doesn't change during streaming. Since blocks are parsed in order and their position in the array is stable, we should use the index.

---

```vue client/src/components/document/ChapterBlock.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
import ChapterBlock from './ChapterBlock.vue'
</script>

<template>
  <div 
    class="chapter-block transition-all duration-200 mb-4"
    @mouseenter="isHovered = true"
    @mouseleave="isHovered = false"
  >
    <!-- Chapter header with copy button -->
    <div v-if="chapter.level > 0">
      <div class="flex items-center justify-between group/header">
        <div :class="`heading-${chapter.level}`">
          <h1 v-if="chapter.level === 1" class="text-3xl font-bold">{{ chapter.title }}</h1>
          <h2 v-else-if="chapter.level === 2" class="text-2xl font-bold">{{ chapter.title }}</h2>
          <h3 v-else-if="chapter.level === 3" class="text-xl font-bold">{{ chapter.title }}</h3>
          <h4 v-else-if="chapter.level === 4" class="text-lg font-bold">{{ chapter.title }}</h4>
          <h5 v-else-if="chapter.level === 5" class="font-bold">{{ chapter.title }}</h5>
          <h6 v-else class="font-bold text-sm">{{ chapter.title }}</h6>
        </div>
        <div class="hidden group-hover/header:flex gap-2 items-center">
          <slot 
            name="chapter-actions" 
            :chapter="chapter"
            :full-content="fullChapterContent"
          >
            <button
              class="btn btn-sm btn-ghost gap-2"
              @click="copyChapterMarkdown"
              :title="`Copy chapter: ${chapter.title}`"
            >
              <i class="fa-solid fa-copy"></i>
              Copy
            </button>
          </slot>
        </div>
      </div>
    </div>

    <!-- Render blocks within chapter -->
    <div class="space-y-4">
      <div v-for="(block, blockIndex) in blocks" :title="`${block.type} - ${block.fileName}`" :key="`${chapter.hash}-block-${blockIndex}`">
        <Code
          :text="block.content"
          :text-language="block.type"
          :fileName="block.fileName"
          :files="files"
          :project="docProject"
          :finished="block.finished"
          :chat="chat"
          :message="message"
          @generate-code="$emit('generate-code', $event)"
          @reload-file="$emit('reload-file', $event)"
          @open-file="$emit('open-file', $event)"
          @save-file="$emit('save-file', $event)"
          @add-file="$emit('add-file', $event)"
          @edit-message="$emit('edit-message', $event)"
          @sub-task="$emit('sub-task', $event)"
          v-if="block.fileName"
        />
        <MarkdownViewer
          :files="files"
          :documentId="documentId"
          :text="block.content"
          @add-file="$emit('add-file', $event)"
          @copy-chapter="$emit('copy-chapter', $event)"
          @create-task="$emit('create-task', $event)"
          v-else
        />        
      </div>
    </div>

    <!-- Render child chapters -->
    <div v-if="chapter.children && chapter.children.length">
      <ChapterBlock
        v-for="(childChapter, childIndex) in chapter.children"
        :key="`${chapter.hash}-child-${childIndex}`"
        :chapter="childChapter"
        :blocks="getChildChapterBlocks(childChapter)"
        :files="files"
        :documentId="documentId"
        :docProject="docProject"
        :chat="chat"
        :message="message"
        @add-file="$emit('add-file', $event)"
        @copy-chapter="handleChildCopy"
        @create-task="$emit('create-task', $event)"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', $event)"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
      >
        <template #chapter-actions="{ chapter: childChapter, fullContent }">
          <slot 
            name="chapter-actions" 
            :chapter="childChapter"
            :full-content="fullContent"
          />
        </template>
      </ChapterBlock>
    </div>
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function isHeading(line) {
  return /^#{1,6}\s+/.test(line)
}

function getHeaderLine(content) {
  const lines = content.split('\n')
  return lines.length > 0 && isHeading(lines[0]) ? lines[0] : ''
}

function stripHeaderFromContent(content) {
  const lines = content.split('\n')
  if (lines.length > 0 && isHeading(lines[0])) {
    return lines.slice(1).join('\n').trim()
  }
  return content
}

function isMarkdownBlockType(blockType) {
  return ['markdown', 'md'].includes(blockType)
}

function getFence(line) {
  const match = line.match(/^( {0,3})(`{3,}|~{3,})(.*)$/)
  if (!match) return null

  return {
    char: match[2][0],
    length: match[2].length,
    info: match[3].trim()
  }
}

function isClosingFence(line, fence) {
  const lineFence = getFence(line)
  return !!(
    lineFence &&
    fence &&
    lineFence.char === fence.char &&
    lineFence.length >= fence.length &&
    !lineFence.info
  )
}

function countClosingFencesAhead(lines, fromIndex, fence) {
  let count = 0
  for (let i = fromIndex + 1; i < lines.length; i++) {
    if (isClosingFence(lines[i], fence)) count++
  }
  return count
}

function isNestedAnonymousFence(lines, index, currentType, currentFence) {
  return (
    isMarkdownBlockType(currentType) &&
    countClosingFencesAhead(lines, index, currentFence) >= 2
  )
}

function collectAllChildContent(chapter) {
  const headerLine = getHeaderLine(chapter.content)
  const contentWithoutHeader = stripHeaderFromContent(chapter.content)
  let allContent = contentWithoutHeader

  if (chapter.children && chapter.children.length) {
    chapter.children.forEach(child => {
      const childFullContent = collectAllChildContent(child)
      allContent += '\n\n' + childFullContent
    })
  }

  return headerLine ? headerLine + '\n\n' + allContent : allContent
}

export default {
  props: {
    chapter: { type: Object, required: true },
    blocks: { type: Array, required: true },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' },
    docProject: { type: Object, default: null },
    chat: { type: Object, default: null },
    message: { type: Object, default: null }
  },
  emits: [
    'add-file',
    'copy-chapter',
    'create-task',
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'edit-message',
    'sub-task'
  ],
  data() {
    return {
      isHovered: false
    }
  },
  computed: {
    fullChapterContent() {
      return collectAllChildContent(this.chapter)
    }
  },
  methods: {
    getChildChapterBlocks(childChapter) {
      const contentWithoutHeader = stripHeaderFromContent(childChapter.content || '')
      return this.parseChildBlocks(contentWithoutHeader)
    },
    parseChildBlocks(content) {
      const blocks = []
      const lines = content.split('\n')
      let currentType = 'markdown'
      let currentContent = []
      let currentFileName = ''
      let inCodeBlock = false
      let currentFence = null
      let nestedFences = []

      const setAllFinished = () => {
        blocks.forEach(b => (b.finished = true))
      }

      const resetCurrentBlock = () => {
        currentType = 'markdown'
        currentContent = []
        currentFileName = ''
        currentFence = null
        nestedFences = []
      }

      const addBlock = () => {
        const blockContent = currentContent.join('\n')
        setAllFinished()
        blocks.push({
          type: currentType,
          content: blockContent,
          fileName: currentFileName,
          renderer: this.getRenderer(currentType, currentFileName),
          finished: false
        })
        resetCurrentBlock()
      }

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        const fence = getFence(line)

        if (!inCodeBlock && fence && fence.info) {
          if (currentContent.length) addBlock()
          const infoParts = fence.info.split(/\s+/).filter(Boolean)
          inCodeBlock = true
          currentFence = fence
          currentType = infoParts[0] || 'text'
          currentFileName = infoParts.slice(1).join(' ')
          continue
        }

        if (inCodeBlock) {
          const nestedFence = nestedFences[nestedFences.length - 1]

          if (nestedFence && isClosingFence(line, nestedFence)) {
            nestedFences.pop()
            currentContent.push(line)
            continue
          }

          if (isMarkdownBlockType(currentType) && fence && fence.info && !isClosingFence(line, currentFence)) {
            nestedFences.push(fence)
            currentContent.push(line)
            continue
          }

          if (!nestedFences.length && isClosingFence(line, currentFence)) {
            if (isNestedAnonymousFence(lines, i, currentType, currentFence)) {
              nestedFences.push(fence)
              currentContent.push(line)
              continue
            }
            addBlock()
            inCodeBlock = false
            continue
          }
        }

        currentContent.push(line)
      }

      if (currentContent.length) addBlock()
      setAllFinished()
      return blocks
    },
    getRenderer(blockType, fileName) {
      if (fileName) return 'code'
      if (['markdown', 'md'].includes(blockType)) return 'md'
      if (['html'].includes(blockType)) return blockType
      return 'code'
    },
    copyChapterMarkdown() {
      const fullContent = this.fullChapterContent
      navigator.clipboard.writeText(fullContent).then(() => {
        this.$emit('copy-chapter', {
          title: this.chapter.title,
          content: fullContent,
          level: this.chapter.level
        })
      }).catch(err => {
        console.error('Failed to copy chapter markdown', err)
      })
    },
    handleChildCopy(chapterData) {
      this.$emit('copy-chapter', chapterData)
    }
  }
}
</script>
```

## Key Changes

1. **Line with blocks loop** (was line ~65):
   - **Before:** `:key="block.hash"`
   - **After:** `:key="`${chapter.hash}-block-${blockIndex}`"`
   - Uses stable chapter hash + block index instead of content-derived hash

2. **Line with child chapters loop** (was line ~105):
   - **Before:** `:key="childChapter.hash"`
   - **After:** `:key="`${chapter.hash}-child-${childIndex}`"`
   - Same pattern for child chapters

## Why This Works

- The **chapter hash** is stable (depends on chapter content, not streaming updates)
- The **block index** is stable (position in array doesn't change during streaming)
- Combined, they create a **unique, stable key** that survives content streaming
- Vue no longer recreates components when block content updates

# Analysis & Solution

The issue is that `CodeViewer.vue` isn't reactively updating the highlighted code display during streaming. The problem is in the `computed` property `effectiveCode` and how the code watcher handles updates.

**Root Causes:**
1. The `code` prop watcher doesn't update `localCode` during streaming
2. `VueCodeHighlighter` component may not be re-rendering on prop changes
3. Missing key or force update mechanism during streaming

**Solution:** Add proper reactivity to track code changes and force component updates during streaming.

```vue client/src/components/CodeViewer.vue
<script setup>
import moment from 'moment'
import { VueCodeHighlighter } from 'vue-code-highlighter'
import 'vue-code-highlighter/dist/style.css'
import hljs from 'highlight.js'
import Editor from './monaco/Editor.vue'
import Collapsible from './Collapsible.vue'
import { EXTENSION_LANGUAGE_MAP } from '../store'
</script>

<template>
  <Collapsible v-model="showCode" class="h-full">
    <template #icon>
      <span class="loading loading-spinner loading-xs" v-if="isStreaming"></span>
      <div class="hover:text-info" @click.stop="$emit('add-file', file)" v-else>
        <i class="fa-solid fa-file-arrow-up"></i>
      </div>
    </template>

    <template #title>
      <div class="flex gap-2 items-center">
        <div class="flex gap-2 items-center flex-1">
          <div class="underline text-link flex gap-2 items-center cursor-pointer" v-if="fileName">
            <div 
              class="hover:text-info tooltip" 
              :data-tip="file" 
              @click.stop="handleFileNameClick($event)"
              :title="file"
            >
              {{ fileName }}
            </div>
          </div>
          <span class="text-sm font-medium opacity-60" v-else>Code</span>

          <div
            class="hover:text-info cursor-pointer"
            :class="editMode && 'text-warning'"
            @click.stop="onEdit"
            title="Edit code"
          >
            <i class="fa-solid fa-edit"></i>
          </div>

          <div
            class="hover:text-info cursor-pointer"
            :class="associatedChat && 'text-success'"
            @click.stop="onTaskClick"
            :title="associatedChat ? 'Open associated chat' : 'Create sub-task'"
          >
            <i :class="associatedChat ? 'fa-solid fa-comments' : 'fa-brands fa-trello'"></i>
          </div>

          <div class="hover:text-info cursor-pointer" @click.stop="loadDiffInfo" title="Refresh diff stats">
            <i class="fa-solid fa-arrows-rotate" :class="{ 'animate-spin': loadingStats }"></i>
          </div>

          <span class="text-xs text-info flex gap-2 items-center" @click.stop="">
            <span v-if="loadingStats">Loading...</span>
            <span @click.stop="toggleView" class="cursor-pointer hover:underline" v-if="stats">
              <i class="fa-solid fa-file-lines" v-if="showDiff"></i>
              <i class="fa-solid fa-code-compare" v-else></i>
              {{ stats }}
            </span>

            <span v-if="last_modification" class="text-xs opacity-75">
              {{ moment(last_modification).fromNow() }}
            </span>
            <span v-if="size">
              {{ size > 1024 ? `${Math.round(size/1024)} KB` : `${size} B` }}
            </span>
          </span>

          <div class="font-mono text-xs truncate trl" v-if="!finished">
            {{ lastLine }}<span class="ml-1 animate-pulse text-info">_</span>
          </div>

          <span
            v-if="hasLocalChanges"
            class="badge badge-warning badge-xs gap-1"
            title="You have unsaved local edits"
          >
            <i class="fa-solid fa-pen-nib"></i> edited
          </span>
        </div>

        <div v-if="stats && !editMode && !isNoChange" class="flex items-center gap-2 ml-2">
          <div
            class="flex h-2 rounded-full overflow-hidden bg-base-200 w-24 relative transition-all duration-300"
            :class="isDangerousChange && 'ring-2 ring-error ring-opacity-70'"
          >
            <div
              class="bg-error transition-all duration-500"
              :style="{ width: deletionPercentage + '%' }"
              :title="`Deletions: ${deletionCount} lines`"
            ></div>
            <div
              class="bg-success transition-all duration-500"
              :style="{ width: additionPercentage + '%' }"
              :title="`Additions: ${additionCount} lines`"
            ></div>
          </div>
          <span class="text-xs font-medium text-base-content/60 w-20 text-right">
            {{ deletionCount }} / {{ additionCount }}
          </span>
          <div v-if="isDangerousChange" class="tooltip tooltip-left" data-tip="Heavy modification detected! Review carefully.">
            <i class="fa-solid fa-triangle-exclamation text-error animate-pulse"></i>
          </div>
        </div>
      </div>
    </template>

    <template #actions>
      <button class="btn btn-sm btn-success btn-outline"
        @click.stop="saveToFile"
        v-if="!isNoChange && file && finished && (showCode || showDiff)"
        :class="{ 'blink-save': isSaving }"
        title="Save to file">
        <i class="fa-solid fa-floppy-disk"></i> Save
      </button>

      <span class="text-success font-console text-xs" v-if="isNoChange">No changes</span>

      <button class="btn btn-sm btn-info btn-outline"
        @click.stop="applyPatchFromPattern"
        v-if="hasPatchPattern && !editMode && !showDiff"
        title="Apply find-and-replace patch">
        <i class="fa-solid fa-band-aid"></i> Patch
      </button>

      <button class="btn btn-sm btn-error btn-outline"
        @click.stop="discardDiffChanges"
        v-if="showDiff && hasDiffEdits"
        title="Discard changes">
        <i class="fa-solid fa-xmark"></i> Discard
      </button>

      <button class="btn btn-sm btn-ghost btn-outline"
        @click.stop="resetLocalChanges"
        v-if="hasLocalChanges"
        title="Reset to original AI-generated code">
        <i class="fa-solid fa-rotate-left"></i> Reset
      </button>

      <button class="btn btn-sm btn-error btn-outline"
        @click.stop="$emit('close')"
        v-if="close"
        title="Close">
        <i class="fa-solid fa-rectangle-xmark"></i>
      </button>
    </template>

    <div class="p-2 flex flex-col gap-2">

      <div @click="runCommand" class="cursor-pointer" v-if="isCommand">
        <i class="fa-solid fa-terminal"></i>
      </div>

      <div v-if="isDangerousChange && !editMode && !showDiff" class="alert alert-warning">
        <svg xmlns="http://www.w3.org/2000/svg" class="stroke-current shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4v2m0 0a9 9 0 1 1 0-18 9 9 0 0 1 0 18z" />
        </svg>
        <span class="text-sm">
          <strong>Heavy modification detected:</strong> {{ changeRiskMessage }}
        </span>
      </div>

      <div v-if="isApplyingPatch" class="alert alert-info">
        <span class="loading loading-spinner loading-sm"></span>
        <span class="text-sm">Applying AI patch, please wait…</span>
      </div>

      <div v-if="changesetErrors.length" class="alert alert-error">
        <svg xmlns="http://www.w3.org/2000/svg" class="stroke-current shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4v2m0 0a9 9 0 1 1 0-18 9 9 0 0 1 0 18z" />
        </svg>
        <div class="flex flex-col gap-1">
          <span class="font-bold">Changeset Errors:</span>
          <div class="text-sm space-y-1">
            <div v-for="(error, idx) in changesetErrors" :key="idx" class="text-xs">
              • {{ error }}
            </div>
          </div>
        </div>
      </div>

      <div class="view-code grow overflow-auto">
        <div :style="{ height: `${editorHeight}px` }">

          <Editor
            :diff="true"
            :originalCode="orgContent"
            v-model="diffEditContent"
            :fileName="file"
            class="h-full"
            v-if="showDiff && !editMode"
          />

          <Editor
            v-model="editContent"
            :fileName="file"
            class="h-full"
            @update:modelValue="onEditorChange"
            v-if="editMode"
          />

          <VueCodeHighlighter
            :key="highlighterKey"
            class="h-full"
            :code="effectiveCode"
            :lang="validatedLanguage"
            :title="fileName"
            v-if="effectiveCode && !editMode && !showDiff"
          />
        </div>
      </div>

      <div class="flex justify-end gap-2" v-if="editMode">
        <button class="btn btn-sm btn-outline" @click="cancelEdit">
          <i class="fa-solid fa-xmark"></i> Cancel
        </button>
        <button class="btn btn-sm btn-warning" @click="applyMessageChange">
          <i class="fa-solid fa-pen-to-square"></i> Apply
        </button>
      </div>

      <div class="flex justify-end gap-2" v-else>
        <button class="btn btn-sm btn-outline" @click.stop="onCopy" title="Copy">
          <i class="fa-solid fa-copy"></i> Copy
        </button>
        <button class="btn btn-sm btn-success btn-outline"
          @click.stop="applyPatch"
          v-if="isPatch"
          title="Apply patch">
          Apply patch
        </button>
      </div>
    </div>

    <modal v-if="showConfirmModal">
        <h3 class="font-bold text-lg">Unsaved Changes</h3>
        <p>You have unsaved changes in the diff editor. What would you like to do?</p>
        <button class="btn btn-error" @click="confirmDiscardDiff">
          <i class="fa-solid fa-trash"></i> Discard
        </button>
        <button class="btn btn-success" @click="confirmApplyDiff">
          <i class="fa-solid fa-check"></i> Apply
        </button>
        <button class="btn" @click="cancelConfirm">
          <i class="fa-solid fa-xmark"></i> Cancel
        </button>
    </modal>
  </Collapsible>
</template>

<script>
export default {
  props: ['close', 'chat', 'code', 'language', 'file', 'diff-option', 'file-diff', 'files', 'project', 'finished', 'showCodeOpened', 'message', 'fromBranch', 'toBranch'],
  emits: ['message-change', 'save-file', 'add-file', 'open-file', 'close', 'sub-task'],
  data() {
    return {
      showDiff: this.diffOption,
      orgContent: null,
      diffEditContent: null,
      diffBaseContent: null,
      diff: this.fileDiff,
      editMode: false,
      editContent: null,
      hasUnsavedFileChanges: false,
      loadingStats: false,
      stats: null,
      last_modification: null,
      size: null,
      showCode: this.$props.showCodeOpened,
      prevScrollTop: 0,
      isAtBottom: true,
      isSaving: false,
      isApplyingPatch: false,
      deletionPercentage: 0,
      additionPercentage: 0,
      deletionCount: 0,
      additionCount: 0,
      isDangerousChange: false,
      changeRiskMessage: '',
      isNewFile: true,
      localCode: null,
      showConfirmModal: false,
      pendingViewSwitch: null,
      changesetErrors: [],
      patchPattern: null,
      highlighterKey: 0,
      codeUpdateCounter: 0
    }
  },
  computed: {
    effectiveCode() {
      return this.localCode !== null ? this.localCode : this.code
    },

    hasLocalChanges() {
      return this.localCode !== null && this.localCode !== this.code
    },

    hasDiffEdits() {
      return this.diffEditContent !== this.diffBaseContent
    },

    editorHeight() {
      const lineCount = this.effectiveCode?.split("\n").length || 10
      const estimated = Math.max(lineCount * 20, 200)
      return Math.min(estimated, 600)
    },

    isStreaming() {
      return !this.finished && this.code
    },

    isPatch() {
      return this.language === 'diff'
    },

    fileName() {
      return this.file?.split('/').reverse()[0]
    },

    isCommand() {
      return this.language === 'bash'
    },

    isNoChange() {
      return this.orgContent === this.code
    },

    fileLanguage() {
      if (this.language) {
        if (hljs.getLanguage(this.language)) return this.language
      }
      const ext = this.file?.split('.').reverse()[0]
      if (ext) return EXTENSION_LANGUAGE_MAP[ext] || ext
      return 'markdown'
    },

    validatedLanguage() {
      const lang = this.fileLanguage
      try {
        if (lang && hljs.getLanguage(lang)) {
          return lang
        }
      } catch (error) {
        console.warn(`Invalid language detected: ${lang}`, error)
      }
      return 'markdown'
    },

    $api() {
      return (this.project?.$api || this.$storex.api)
    },

    lastLine() {
      return this.code?.split("\n").reverse()[0]
    },

    associatedChat() {
      return this.$service.chat.findChatByFileAndMessage({
        chat: this.chat,
        file: this.file,
        messageId: this.message?.doc_id
      })
    },
    isJSONChangeset() {
      return this.language === 'json-changeset'
    },
    hasPatchPattern() {
      return this.patchPattern !== null
    }
  },
  watch: {
    async finished() {
      if (this.finished && this.showCode) {
        await this.loadDiffInfo()
        if (!this.isNewFile && this.stats && !this.isNoChange) {
          this.showDiff = true
        }
      }
      if (this.chat?.mode === 'vibe') {
        this.saveToFile()
      }
    },
    code() {
      this.changesetErrors = []
      this.detectPatchPattern()
      this.codeUpdateCounter++
      this.highlighterKey++
      this.$nextTick(() => {
        const viewCode = this.$el?.querySelector('.view-code')
        if (!viewCode) return
        if (this.isAtBottom) {
          viewCode.scrollTop = viewCode.scrollHeight
        } else {
          viewCode.scrollTop = this.prevScrollTop
        }
      })
    },
    fromBranch() {
      if (this.showCode) {
        this.loadDiffInfo()
      }
    },
    toBranch() {
      if (this.showCode) {
        this.loadDiffInfo()
      }
    }
  },
  mounted() {
    if (this.chat?.mode === 'vibe') {
      this.showCode = false
    }
    if (this.finished && this.showCode) {
      this.loadDiffInfo()
    }
    this.detectPatchPattern()
    const viewCode = this.$el?.querySelector('.view-code')
    if (viewCode) viewCode.addEventListener('scroll', this.saveScrollPosition)
  },
  beforeUnmount() {
    const viewCode = this.$el?.querySelector('.view-code')
    if (viewCode) viewCode.removeEventListener('scroll', this.saveScrollPosition)
  },
  methods: {
    detectPatchPattern() {
      if (!this.code) {
        this.patchPattern = null
        return
      }

      const patchRegex = /^<<<<\s*\n([\s\S]*?)\n====\s*\n([\s\S]*?)\n>>>>\s*$/m
      const match = this.code.match(patchRegex)

      if (match) {
        this.patchPattern = {
          oldContent: match[1],
          newContent: match[2]
        }
      } else {
        this.patchPattern = null
      }
    },

    async applyPatchFromPattern() {
      if (!this.patchPattern || !this.file) return

      try {
        this.isApplyingPatch = true

        const patchedContent = this.patchPattern.newContent

        await this.$api.files.patch({
          file_path: this.file,
          content: patchedContent
        })

        this.applyUserChange(patchedContent)
        this.$ui?.showNotification?.({
          type: 'success',
          message: 'Patch applied successfully'
        })
      } catch (error) {
        console.error('Error applying patch pattern:', error)
        this.$ui?.showNotification?.({
          type: 'error',
          message: 'Failed to apply patch: ' + (error?.message || 'Unknown error')
        })
      } finally {
        this.isApplyingPatch = false
      }
    },

    handleFileNameClick(event) {
      if (event.ctrlKey || event.metaKey) {
        this.$storex.ui.openFileInViewer(this.file)
      } else {
        this.$emit('open-file', this.file)
      }
    },

    applyChangeset() {
      try {
        const changeset = JSON.parse(this.code)
        if (!Array.isArray(changeset)) {
          this.changesetErrors.push('Changeset must be a JSON array')
          return
        }

        let processedCode = this.code
        changeset.forEach((change, idx) => {
          try {
            const { search_type, search, replace, replace_all } = change
            if (!search_type || !search || replace === undefined) {
              throw new Error('Missing required fields: search_type, search, or replace')
            }

            let result
            if (search_type === 'plain') {
              const searchIndex = processedCode.indexOf(search)
              if (searchIndex === -1) {
                throw new Error(`Pattern not found in code`)
              }

              if (replace_all) {
                processedCode = processedCode.split(search).join(replace)
              } else {
                processedCode = processedCode.substring(0, searchIndex) +
                  replace +
                  processedCode.substring(searchIndex + search.length)
              }
            } else if (search_type === 'regex') {
              try {
                const flags = replace_all ? 'g' : ''
                const regex = new RegExp(search, flags)
                processedCode = processedCode.replace(regex, replace)
              } catch (regexError) {
                throw new Error(`Invalid regex pattern: ${regexError.message}`)
              }
            } else {
              throw new Error(`Unknown search_type: ${search_type}. Must be 'plain' or 'regex'`)
            }
          } catch (error) {
            this.changesetErrors.push(`[Item ${idx}] ${error.message}`)
          }
        })

        this.localCode = processedCode
      } catch (parseError) {
        this.changesetErrors.push(`Failed to parse changeset JSON: ${parseError.message}`)
      }
    },

    applyUserChange(newContent) {
      if (!newContent) return
      this.localCode = newContent
      this.diffEditContent = newContent
      this.diffBaseContent = newContent
      this.editMode = false
      this.showDiff = !!this.orgContent
      this.hasUnsavedFileChanges = true
    },

    resetLocalChanges() {
      this.localCode = null
      this.diffEditContent = this.code
      this.diffBaseContent = this.code
      this.hasUnsavedFileChanges = false
      this.showDiff = !!this.orgContent && !this.isNoChange
    },

    parseStatsString() {
      if (!this.stats) return { deletions: 0, insertions: 0 }
      const deleteMatch = this.stats.match(/(\d+) deletion/)
      const insertMatch = this.stats.match(/(\d+) insertion/)
      return {
        deletions: deleteMatch ? parseInt(deleteMatch[1]) : 0,
        insertions: insertMatch ? parseInt(insertMatch[1]) : 0
      }
    },

    calculateDiffPercentages() {
      if (!this.stats || !this.orgContent) return
      const { deletions, insertions } = this.parseStatsString()
      const total = deletions + insertions
      this.deletionCount = deletions
      this.additionCount = insertions
      if (total === 0) {
        this.deletionPercentage = 0
        this.additionPercentage = 0
        return
      }
      this.deletionPercentage = (deletions / total) * 100
      this.additionPercentage = (insertions / total) * 100
      this.evaluateChangeRisk()
    },

    evaluateChangeRisk() {
      const { deletions, insertions } = this.parseStatsString()
      const originalLines = this.orgContent?.split('\n').length || 1
      const newLines = this.effectiveCode?.split('\n').length || 1
      const deletionRatio = deletions / originalLines
      const lineChangeRatio = Math.abs(newLines - originalLines) / originalLines
      const totalChanges = deletions + insertions
      const changeIntensity = totalChanges / originalLines
      const DANGEROUS_DELETION_RATIO = 0.4
      const DANGEROUS_INTENSITY = 0.5
      const DANGEROUS_LINE_LOSS = 0.3
      const isDeletion = deletionRatio > DANGEROUS_DELETION_RATIO
      const isHighIntensity = changeIntensity > DANGEROUS_INTENSITY
      const isLineLoss = lineChangeRatio > DANGEROUS_LINE_LOSS && deletions > insertions
      this.isDangerousChange = isDeletion || isHighIntensity || isLineLoss
      this.changeRiskMessage = this.generateRiskMessage(deletionRatio, changeIntensity, lineChangeRatio, deletions, insertions)
    },

    generateRiskMessage(delRatio, intensity, lineRatio, deletions, insertions) {
      if (delRatio > 0.4) return `${(delRatio * 100).toFixed(0)}% of original content deleted. Critical review recommended.`
      if (lineRatio > 0.3 && deletions > insertions) return `File lost ~${Math.round(lineRatio * 100)}% of its content. Check if changes are intentional.`
      if (intensity > 0.5) return `Over 50% of file modified. This may indicate significant structural changes.`
      return 'High modification level detected.'
    },

    applyPatch() {
      this.$projects.applyPatch({ patch: this.code })
    },

    async applyPatchFromAI() {
      if (!this.file || this.isApplyingPatch) return
      try {
        this.isApplyingPatch = true
        const response = await this.$api.run.patch({
          file_path: this.file,
          partial_content: this.effectiveCode
        })
        if (response?.content) {
          this.applyUserChange(response.content)
        } else {
          console.warn('Patch API returned no content', response)
        }
      } catch (error) {
        console.error('Error applying patch from AI:', error)
        this.$ui?.showNotification?.({
          type: 'error',
          message: 'Failed to apply patch: ' + (error?.message || 'Unknown error')
        })
      } finally {
        this.isApplyingPatch = false
      }
    },

    toggleView() {
      if (this.hasDiffEdits) {
        this.pendingViewSwitch = 'toggle'
        this.showConfirmModal = true
      } else {
        this.showDiff = !this.showDiff
      }
    },

    async loadDiffInfo() {
      try {
        this.loadingStats = true
        if (this.file) {
          const diffRequest = {
            path: this.file,
            content: this.effectiveCode
          }
          if (this.fromBranch) diffRequest.from_branch = this.fromBranch
          if (this.toBranch) diffRequest.to_branch = this.toBranch

          const { diff, stats, last_modification, size } = await this.$api.files.diff(diffRequest)
          this.diff = diff
          this.stats = stats
          this.last_modification = last_modification
          this.size = size
          if (!stats && diff) this.stats = 'File changes'

          let content = ""
          try {
            if (this.fromBranch) {
              const { content: fileContent } = await this.$api.repo.readFromBranch(this.file, this.fromBranch)
              content = fileContent
              this.isNewFile = !fileContent
            } else {
              const { content: fileContent } = await this.$api.files.read(this.file)
              content = fileContent
              this.isNewFile = !fileContent
            }
          } catch (ex) {
            console.error(ex)
            this.isNewFile = true
          }

          this.orgContent = content
          this.diffEditContent = this.effectiveCode
          this.diffBaseContent = this.effectiveCode
          this.calculateDiffPercentages()

          if (this.isJSONChangeset) {
            this.applyChangeset()
          }
        }
      } finally {
        this.loadingStats = false
      }
    },

    onEdit() {
      if (this.editMode) {
        this.cancelEdit()
        return
      }
      this.editContent = this.effectiveCode
      this.editMode = true
      this.showDiff = false
      this.hasUnsavedFileChanges = false
    },

    cancelEdit() {
      this.editMode = false
      this.editContent = null
    },

    onEditorChange(value) {
      this.editContent = value
      this.hasUnsavedFileChanges = true
    },

    applyMessageChange() {
      this.$emit('message-change', { orgContent: this.effectiveCode, newContent: this.editContent })
      this.applyUserChange(this.editContent)
      this.cancelEdit()
    },

    discardDiffChanges() {
      this.diffEditContent = this.diffBaseContent
      this.showDiff = false
    },

    confirmApplyDiff() {
      this.localCode = this.diffEditContent
      this.diffBaseContent = this.diffEditContent
      this.showConfirmModal = false
      this.pendingViewSwitch = null
      if (this.pendingViewSwitch === 'toggle') {
        this.showDiff = !this.showDiff
      }
    },

    confirmDiscardDiff() {
      this.diffEditContent = this.diffBaseContent
      this.showConfirmModal = false
      const shouldToggle = this.pendingViewSwitch === 'toggle'
      this.pendingViewSwitch = null
      if (shouldToggle) {
        this.showDiff = !this.showDiff
      }
    },

    cancelConfirm() {
      this.showConfirmModal = false
      this.pendingViewSwitch = null
    },

    async saveToFile() {
      this.triggerSaveAnimation()
      let content
      if (this.editMode && this.editContent) {
        content = this.editContent
      } else if (this.showDiff && this.diffEditContent) {
        content = this.diffEditContent
      } else {
        content = this.effectiveCode
      }
      this.$emit('save-file', { file: this.file, content })
      this.hasUnsavedFileChanges = false
      if (this.editMode) this.cancelEdit()
      this.showDiff = false
      this.localCode = null
      this.diffEditContent = null
      this.diffBaseContent = null
      await this.loadDiffInfo()
    },

    triggerSaveAnimation() {
      this.isSaving = true
      setTimeout(() => { this.isSaving = false }, 800)
    },

    runCommand() {
      this.$storex.api.apps.runScript(this.code)
    },

    onCopy() {
      this.$ui.copyTextToClipboard(this.effectiveCode)
    },

    createSubTask() {
      const content = [
        '```' + this.fileLanguage + ' ' + this.file,
        this.effectiveCode,
        '```'
      ].join('\n')
      this.$emit('sub-task', { file: this.file, content })
    },

    onTaskClick() {
      if (this.associatedChat) {
        this.$chats.setActiveChat(this.associatedChat)
      } else {
        this.createSubTask()
      }
    },

    saveScrollPosition() {
      const viewCode = this.$el?.querySelector('.view-code')
      if (!viewCode) return
      this.prevScrollTop = viewCode.scrollTop
      const distanceFromBottom = viewCode.scrollHeight - viewCode.scrollTop - viewCode.clientHeight
      this.isAtBottom = distanceFromBottom <= 40
    }
  }
}
</script>

